 "content": "from collections import Counter


def transform(grid):
    """Translate the distinct object adjacent to the full 2 stripe and add 8 behind it."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    stripe_rows = [r for r in range(h) if all(v == 2 for v in grid[r])]
    stripe_cols = [c for c in range(w) if all(grid[r][c] == 2 for r in range(h))]
    if stripe_rows:
        axis, stripe = "row", stripe_rows[0]
    elif stripe_cols:
        axis, stripe = "col", stripe_cols[0]
    else:
        return out

    counts = Counter(v for row in grid for v in row if v != 2)
    if not counts:
        return out
    background = counts.most_common(1)[0][0]
    object_colors = [v for v in counts if v != background]
    if not object_colors:
        return out
    obj = min(object_colors, key=lambda color: counts[color])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == obj]
    if not cells:
        return out
    rmin, rmax = min(r for r, c in cells), max(r for r, c in cells)
    cmin, cmax = min(c for r, c in cells), max(c for r, c in cells)

    if axis == "row":
        if rmax < stripe:
            dr = stripe - 1 - rmax
            divider = rmin + dr - 1
        else:
            dr = stripe + 1 - rmin
            divider = rmax + dr + 1
        for r, c in cells:
            out[r][c] = background
        for r, c in cells:
            out[r + dr][c] = obj
        if 0 <= divider < h:
            out[divider] = [8] * w
    else:
        if cmax < stripe:
            dc = stripe - 1 - cmax
            divider = cmin + dc - 1
        else:
            dc = stripe + 1 - cmin
            divider = cmax + dc + 1
        for r, c in cells:
            out[r][c] = background
        for r, c in cells:
            out[r][c + dc] = obj
        if 0 <= divider < w:
            for r in range(h):
                out[r][divider] = 8
    return out


if __name__ == "__main__":
    import json
    test = [[1] * 12 for _ in range(26)]
    test[16] = [6,1,6,1,6,6,6,6,1,1,1,1]
    test[17] = [1,6,6,6,6,6,6,6,1,1,1,1]
    test[18] = [6,6,6,6,6,6,6,1,6,1,1,1]
    test[19] = [6,6,6,6,6,6,6,6,6,6,1,1]
    test[20] = [6,6,6,6,6,6,6,1,1,1,1,1]
    test[21] = [6,6,6,6,6,6,6,6,1,1,1,1]
    test[24] = [2] * 12
    print(json.dumps(transform(test)))
